content:
/* Hairline + bench so native screenshot size stays visible on the card. */
.stage {
  background-color: var(--diff-canvas);
  background-image: repeating-conic-gradient(var(--muted) 0% 25%, var(--diff-canvas) 0% 50%);
  background-size: 12px 12px;
  box-shadow: inset 0 0 0 1px var(--border);
}
